write a program in dart which convert an png image's color to black and white. Just the answer, thanks.
</request>

Reply (it may be cut off mid-sentence; judge only what is there):
<reply>
```dart
import 'dart:io';
import 'package:image/image.dart' as img;

void main() {
  // Load the image
  final file = File('input.png');
  if (!file.existsSync()) {
    print('File not found.');
    return;
  }

  final bytes = file.readAsBytesSync();
  final image = img.decodeImage(bytes);

  if (image == null) {
    print('Failed to decode image.');
    return;
  }

  // Convert to grayscale (black and white)
  final bwImage = img.grayscale(image);

  // Encode back to PNG
  final pngBytes = img.encodePng(bwImage);

  // Save the result
  final outputFile = File('output_bw.png');
  outputFile.writeAsBytesSync(pngBytes);

  print('Black and white image saved as output_bw.png');
}
